-- 퀴즈 마스터 데이터 (21일 챌린지용)
-- Day 1-21 퀴즈 문제
-- missionId 포함 버전

BEGIN;

INSERT INTO quizzes (mission_id, day, question, options, correct_answer, points, explanation, is_active, created_at, updated_at)
SELECT
  (SELECT id FROM missions WHERE record_type = 'QUIZ') as mission_id,
  day, question, options, correct_answer, points, explanation, is_active, created_at, updated_at
FROM (VALUES
  (1, '이너뷰티란 무엇인가요?', '[{"label":"1","value":"외모를 가꾸는 것"},{"label":"2","value":"내면의 건강과 아름다움을 추구하는 것"},{"label":"3","value":"화장품을 바르는 것"},{"label":"4","value":"운동만 하는 것"}]'::json, 2, 200, '이너뷰티는 내면의 건강과 아름다움을 추구하는 개념으로, 영양, 운동, 수면 등 전반적인 생활습관을 통해 건강한 몸과 마음을 만드는 것을 의미합니다.', true, NOW(), NOW()),
  (2, '하루 권장 물 섭취량은?', '[{"label":"1","value":"500ml"},{"label":"2","value":"1L"},{"label":"3","value":"2L"},{"label":"4","value":"3L"}]'::json, 3, 200, '성인 기준 하루 권장 물 섭취량은 약 2L(8잔)입니다. 충분한 수분 섭취는 신진대사 촉진, 피부 건강, 노폐물 배출에 도움이 됩니다.', true, NOW(), NOW()),
  (3, '항산화 효과가 있는 영양소는?', '[{"label":"1","value":"비타민 C"},{"label":"2","value":"탄수화물"},{"label":"3","value":"포화지방"},{"label":"4","value":"나트륨"}]'::json, 1, 200, '비타민 C는 강력한 항산화 작용을 하며, 활성산소를 제거하여 세포 손상을 방지하고 노화를 늦추는 데 도움을 줍니다.', true, NOW(), NOW()),
  (4, '피부 건강에 좋은 영양소는?', '[{"label":"1","value":"비타민 E"},{"label":"2","value":"설탕"},{"label":"3","value":"카페인"},{"label":"4","value":"알코올"}]'::json, 1, 200, '비타민 E는 피부의 수분 보유력을 높이고, 항산화 작용으로 피부 노화를 방지하며, 피부 재생을 돕는 중요한 영양소입니다.', true, NOW(), NOW()),
  (5, '장 건강에 도움이 되는 것은?', '[{"label":"1","value":"프로바이오틱스"},{"label":"2","value":"패스트푸드"},{"label":"3","value":"탄산음료"},{"label":"4","value":"인스턴트 식품"}]'::json, 1, 200, '프로바이오틱스는 장내 유익균을 증식시켜 장 건강을 개선하고, 소화 기능을 향상시키며, 면역력 강화에도 도움을 줍니다.', true, NOW(), NOW()),
  (6, '숙면에 도움이 되는 습관은?', '[{"label":"1","value":"자기 전 스마트폰 사용"},{"label":"2","value":"규칙적인 수면 시간"},{"label":"3","value":"카페인 섭취"},{"label":"4","value":"과식"}]'::json, 2, 200, '규칙적인 수면 시간을 유지하면 생체 리듬이 안정되어 수면의 질이 향상됩니다. 매일 같은 시간에 자고 일어나는 습관이 중요합니다.', true, NOW(), NOW()),
  (7, '스트레스 관리에 효과적인 방법은?', '[{"label":"1","value":"명상과 호흡"},{"label":"2","value":"과음"},{"label":"3","value":"과식"},{"label":"4","value":"수면 부족"}]'::json, 1, 200, '명상과 깊은 호흡은 부교감신경을 활성화시켜 심신을 안정시키고, 스트레스 호르몬인 코르티솔 수치를 낮추는 데 효과적입니다.', true, NOW(), NOW()),
  (8, '근육 건강에 필요한 영양소는?', '[{"label":"1","value":"단백질"},{"label":"2","value":"설탕"},{"label":"3","value":"포화지방"},{"label":"4","value":"알코올"}]'::json, 1, 200, '단백질은 근육을 구성하는 주요 성분이며, 근육 생성과 회복에 필수적입니다. 체중 1kg당 0.8~1.2g의 단백질 섭취가 권장됩니다.', true, NOW(), NOW()),
  (9, '면역력 강화에 도움이 되는 것은?', '[{"label":"1","value":"비타민 D"},{"label":"2","value":"수면 부족"},{"label":"3","value":"스트레스"},{"label":"4","value":"운동 부족"}]'::json, 1, 200, '비타민 D는 면역 세포의 기능을 조절하고 면역 반응을 강화하는 데 중요한 역할을 합니다. 햇빛 노출이나 보충제를 통해 섭취할 수 있습니다.', true, NOW(), NOW()),
  (10, '혈액순환 개선에 좋은 활동은?', '[{"label":"1","value":"스트레칭"},{"label":"2","value":"장시간 앉아있기"},{"label":"3","value":"흡연"},{"label":"4","value":"과음"}]'::json, 1, 200, '규칙적인 스트레칭은 근육의 긴장을 풀어주고 혈관을 확장시켜 혈액순환을 개선합니다. 특히 장시간 앉아있는 경우 더욱 중요합니다.', true, NOW(), NOW()),
  (11, '디톡스에 도움이 되는 식품은?', '[{"label":"1","value":"녹차"},{"label":"2","value":"튀김"},{"label":"3","value":"가공식품"},{"label":"4","value":"탄산음료"}]'::json, 1, 200, '녹차에 함유된 카테킨 성분은 항산화 작용을 하며, 체내 노폐물과 독소 배출을 돕고 신진대사를 촉진합니다.', true, NOW(), NOW()),
  (12, '콜라겐 생성에 필요한 영양소는?', '[{"label":"1","value":"비타민 C"},{"label":"2","value":"설탕"},{"label":"3","value":"나트륨"},{"label":"4","value":"포화지방"}]'::json, 1, 200, '비타민 C는 콜라겐 합성에 필수적인 영양소로, 피부 탄력 유지와 주름 예방에 중요한 역할을 합니다.', true, NOW(), NOW()),
  (13, '뼈 건강에 중요한 영양소는?', '[{"label":"1","value":"칼슘"},{"label":"2","value":"설탕"},{"label":"3","value":"카페인"},{"label":"4","value":"알코올"}]'::json, 1, 200, '칼슘은 뼈와 치아의 주요 구성 성분으로, 골밀도 유지와 골다공증 예방에 필수적입니다. 비타민 D와 함께 섭취하면 흡수율이 높아집니다.', true, NOW(), NOW()),
  (14, '에너지 대사에 필요한 비타민은?', '[{"label":"1","value":"비타민 B군"},{"label":"2","value":"비타민 K"},{"label":"3","value":"비타민 A"},{"label":"4","value":"비타민 E"}]'::json, 1, 200, '비타민 B군(B1, B2, B6, B12 등)은 탄수화물, 지방, 단백질의 에너지 대사에 관여하며, 피로 회복과 신경 기능 유지에 중요합니다.', true, NOW(), NOW()),
  (15, '항염 효과가 있는 식품은?', '[{"label":"1","value":"오메가-3"},{"label":"2","value":"트랜스지방"},{"label":"3","value":"설탕"},{"label":"4","value":"가공육"}]'::json, 1, 200, '오메가-3 지방산은 강력한 항염 작용을 하며, 만성 염증을 감소시키고 심혈관 건강, 뇌 건강에 도움을 줍니다.', true, NOW(), NOW()),
  (16, '눈 건강에 좋은 영양소는?', '[{"label":"1","value":"루테인"},{"label":"2","value":"설탕"},{"label":"3","value":"포화지방"},{"label":"4","value":"나트륨"}]'::json, 1, 200, '루테인은 망막의 황반 색소를 구성하는 성분으로, 눈의 피로를 줄이고 황반변성 예방에 도움을 줍니다.', true, NOW(), NOW()),
  (17, '두뇌 건강에 좋은 영양소는?', '[{"label":"1","value":"오메가-3"},{"label":"2","value":"설탕"},{"label":"3","value":"트랜스지방"},{"label":"4","value":"알코올"}]'::json, 1, 200, '오메가-3는 뇌 세포막의 주요 구성 성분으로, 인지 기능 향상, 기억력 개선, 치매 예방에 도움을 줍니다.', true, NOW(), NOW()),
  (18, '혈당 조절에 도움이 되는 것은?', '[{"label":"1","value":"식이섬유"},{"label":"2","value":"설탕"},{"label":"3","value":"흰 빵"},{"label":"4","value":"탄산음료"}]'::json, 1, 200, '식이섬유는 당의 흡수 속도를 늦춰 혈당의 급격한 상승을 방지하고, 포만감을 주어 체중 관리에도 도움을 줍니다.', true, NOW(), NOW()),
  (19, '간 건강에 좋은 영양소는?', '[{"label":"1","value":"밀크씨슬"},{"label":"2","value":"알코올"},{"label":"3","value":"지방"},{"label":"4","value":"설탕"}]'::json, 1, 200, '밀크씨슬의 실리마린 성분은 간세포를 보호하고 재생을 돕며, 간 해독 기능을 향상시킵니다.', true, NOW(), NOW()),
  (20, '심혈관 건강에 좋은 습관은?', '[{"label":"1","value":"규칙적인 유산소 운동"},{"label":"2","value":"흡연"},{"label":"3","value":"과음"},{"label":"4","value":"고지방 식단"}]'::json, 1, 200, '규칙적인 유산소 운동은 심장 기능을 강화하고, 혈액순환을 개선하며, 콜레스테롤 수치를 조절하여 심혈관 질환 예방에 효과적입니다.', true, NOW(), NOW()),
  (21, '건강한 노화를 위한 가장 중요한 요소는?', '[{"label":"1","value":"균형 잡힌 생활습관"},{"label":"2","value":"과식"},{"label":"3","value":"운동 부족"},{"label":"4","value":"수면 부족"}]'::json, 1, 200, '건강한 노화를 위해서는 균형 잡힌 영양 섭취, 규칙적인 운동, 충분한 수면, 스트레스 관리 등 전반적인 생활습관 관리가 가장 중요합니다.', true, NOW(), NOW())
) AS t(day, question, options, correct_answer, points, explanation, is_active, created_at, updated_at);

COMMIT;

-- 삽입 결과 확인
SELECT COUNT(*) as total_quizzes FROM quizzes WHERE is_active = true;
